import base64
import os

from google.cloud import vision


def detect_labels(image_path: str, max_results: int = 10):
    client = vision.ImageAnnotatorClient()
    with open(image_path, "rb") as f:
        content = f.read()

    image = vision.Image(content=content)
    response = client.label_detection(image=image, max_results=max_results)

    if response.error.message:
        raise RuntimeError(response.error.message)

    return [
        {
            "description": label.description,
            "score": float(label.score),
            "topicality": float(label.topicality),
        }
        for label in response.label_annotations
    ]


def detect_objects(image_path: str, max_results: int = 10):
    client = vision.ImageAnnotatorClient()
    with open(image_path, "rb") as f:
        content = f.read()

    image = vision.Image(content=content)
    response = client.object_localization(image=image)

    if response.error.message:
        raise RuntimeError(response.error.message)

    objects = []
    for obj in response.localized_object_annotations[:max_results]:
        objects.append(
            {
                "name": obj.name,
                "score": float(obj.score),
                "bounding_poly": [
                    {"x": float(v.x), "y": float(v.y)}
                    for v in obj.bounding_poly.normalized_vertices
                ],
            }
        )
    return objects


def detect_labels_from_base64(image_b64: str, max_results: int = 10):
    client = vision.ImageAnnotatorClient()
    image = vision.Image(content=base64.b64decode(image_b64))
    response = client.label_detection(image=image, max_results=max_results)

    if response.error.message:
        raise RuntimeError(response.error.message)

    return [
        {
            "description": label.description,
            "score": float(label.score),
            "topicality": float(label.topicality),
        }
        for label in response.label_annotations
    ]


GOOGLE_APPLICATION_CREDENTIALS = os.getenv("GOOGLE_APPLICATION_CREDENTIALS")
